def good(part, total):
    return None if total == 0 else part / total
cases = share_cases()
assert len(cases) >= 2, "write at least two cases"
for part, total, expected in cases:
    assert good(part, total) == expected, (part, total, expected)

def raises(part, total):
    return part / total
def fails(fn):
    for part, total, expected in share_cases():
        try:
            if fn(part, total) != expected:
                return True
        except Exception:
            return True
    return False
assert fails(raises)

def zero(part, total):
    return 0.0 if total == 0 else part / total
assert any(zero(p, t) != e for p, t, e in share_cases())

def pct(part, total):
    return None if total == 0 else part / total * 100
assert any(pct(p, t) != e for p, t, e in share_cases())
